// FUNCTION: BFME2 0x004DF547 size=478 name=?update@ObjectDefectionHelper@@UAE?AW4UpdateSleepTime@@XZ evidence=N:ledger tier=B hypothesis:name:Z
UpdateSleepTime ObjectDefectionHelper::update()
{
	Object *obj = getObject();
	Drawable *draw = obj->getDrawable();

	// if we are here, we should be an undetected defector, but
	// just in case someone has changed us behind our backs...
	if (!obj->getIsUndetectedDefector())
		return UPDATE_SLEEP_FOREVER;

	UnsignedInt now = TheGameLogic->getFrame();
	UnsignedInt detectionEnd = m_windowEndFrame;
	if (now >= detectionEnd)
	{
		obj->friend_setUndetectedDefector(false);

		// timer has reached zero, so we flash white once
		if (draw && m_doFX)
		{
			RGBColor white(1.0f, 1.0f, 1.0f);
			draw->flashAsSelected(&white);

			AudioEventRTS defectorVulnerableSound(TheAudio->getMiscAudio()->m_defectorTimerDingSound, 0);
			defectorVulnerableSound.setObjectID(obj->getID());
			TheAudio->addAudioEvent(&defectorVulnerableSound);
		}
		return UPDATE_SLEEP_FOREVER;
	}

	// dead or attacking... our cover is blown.
	if ((obj->getAI() != NULL && obj->isEffectivelyDead()) || obj->testStatus(OBJECT_STATUS_IS_FIRING_WEAPON))
	{
		obj->friend_setUndetectedDefector(false);
		return UPDATE_SLEEP_FOREVER;
	}

	if (draw && m_doFX) // skip fx if merely 'invulnerable'
	{
		Bool lastPhase = (((Int)m_flashPhase) & 1); // were we in a flashy phase last frame?
		UnsignedInt timeLeft = detectionEnd - now;
		m_flashPhase += 0.5f * (1.0f - ((Real)timeLeft / (10 * BfmeLogicFramesPerSecond)));
		Bool thisPhase = (((Int)m_flashPhase) & 1); // are we in a flashy phase this frame?

		if (lastPhase && !thisPhase)
		{
			draw->flashAsSelected(NULL);

			AudioEventRTS defectorTimerSound(TheAudio->getMiscAudio()->m_defectorTimerTickSound, 0);
			defectorTimerSound.setObjectID(obj->getID());
			TheAudio->addAudioEvent(&defectorTimerSound);
		}
	}

	return UPDATE_SLEEP_NONE;
}

// FUNCTION: BFME2 0x004DF725 size=73 name=?startDefectionTimer@ObjectDefectionHelper@@QAEXI_N@Z evidence=N:ledger tier=B hypothesis:Z
void ObjectDefectionHelper::startDefectionTimer(UnsignedInt duration, Bool doFX)
{
	Object *obj = getObject();
	if (!obj->getIsUndetectedDefector())
	{
		setWakeFrame(obj, UPDATE_SLEEP_FOREVER);
		return;
	}
	UnsignedInt currentFrame = TheGameLogic->getFrame();
	m_windowStartFrame = currentFrame;
	m_windowEndFrame = currentFrame + duration;
	m_flashPhase = 0.0f;
	m_doFX = doFX;
	setWakeFrame(obj, UPDATE_SLEEP_NONE);
}

// FUNCTION: BFME2 0x004DF76E size=84 name=?xfer@ObjectDefectionHelper@@MAEXPAVXfer@@@Z evidence=N:ledger tier=B hypothesis:Z
void ObjectDefectionHelper::xfer(Xfer *xfer)
{
	ObjectHelper::xfer(xfer);
	if (xfer->IsLightCRC())
		return;
	xfer->Version1();
	*xfer == m_windowStartFrame;
	*xfer == m_windowEndFrame;
	*xfer == m_flashPhase;
	*xfer == m_doFX;
}
